#pragma once
#include "Wire.h"
template<>struct Wire<InterceptionKeyStroke>;
template<>struct Wire<InterceptionMouseStroke>;
template<>struct Wire<InterceptionKeyStroke> {static Json Encode(const InterceptionKeyStroke& v){Json j=Json::object();j["code"]=EncodeWire(v.code);j["state"]=EncodeWire(v.state);j["information"]=EncodeWire(v.information);return j;}static void Decode(const Json& j,InterceptionKeyStroke& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="code")DecodeWire(it.value(),v.code);else if(it.key()=="state")DecodeWire(it.value(),v.state);else if(it.key()=="information")DecodeWire(it.value(),v.information);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<InterceptionMouseStroke> {static Json Encode(const InterceptionMouseStroke& v){Json j=Json::object();j["state"]=EncodeWire(v.state);j["flags"]=EncodeWire(v.flags);j["rolling"]=EncodeWire(v.rolling);j["x"]=EncodeWire(v.x);j["y"]=EncodeWire(v.y);j["information"]=EncodeWire(v.information);return j;}static void Decode(const Json& j,InterceptionMouseStroke& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="state")DecodeWire(it.value(),v.state);else if(it.key()=="flags")DecodeWire(it.value(),v.flags);else if(it.key()=="rolling")DecodeWire(it.value(),v.rolling);else if(it.key()=="x")DecodeWire(it.value(),v.x);else if(it.key()=="y")DecodeWire(it.value(),v.y);else if(it.key()=="information")DecodeWire(it.value(),v.information);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
